import{Lt as e,Vt as t,Z as n,_t as r,bt as i,vt as a}from"./chunks/framework.CsLlEPF4.js";import"./chunks/assets.Cofv-KFd.js";var o=JSON.parse(`{"title":"在 Word 中插入参考文献","description":"","frontmatter":{"title":"在 Word 中插入参考文献","icon":"file-word","date":"2023-06-28T21:17:07.000Z","updated":"2023-07-21T19:01:31.000Z"},"headers":[],"relativePath":"user-guide/ms-word-plugin.md","filePath":"wiki/user-guide/ms-word-plugin.md"}`),s={name:`user-guide/ms-word-plugin.md`};function c(n,o,s,c,l,u){let d=t(`NolebaseGitContributors`),f=t(`NolebaseGitChangelog`);return e(),r(`div`,null,[o[0]||=a(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /user-guidems-word-plugin.md for this page in Markdown format</div><h1 id="在-word-中插入参考文献" tabindex="-1">在 Word 中插入参考文献 <a class="header-anchor" href="#在-word-中插入参考文献" aria-label="Permalink to “在 Word 中插入参考文献”">​</a></h1><p>这些是使用 Zotero for MS Office Word 插件的说明。</p><p>要在 WPS 中使用插件，请参见 <a href="./wps-plugin">在 WPS 中使用 Zotero Word 插件</a>。</p><h2 id="zotero-word-插件选项卡" tabindex="-1">Zotero Word 插件选项卡 <a class="header-anchor" href="#zotero-word-插件选项卡" aria-label="Permalink to “Zotero Word 插件选项卡”">​</a></h2><p><img src="/assets/word-zotero%E7%AA%97%E6%A0%BC.CCT-CRnr.png" alt="Zotero Word 插件选项卡" width="1022" height="298"></p><p>一般情况下，Zotero 安装时会安装 Zotero Word 插件，其会在 Microsoft Word 里添加一个 Zotero 选项卡。如果你的 Word 里没有 Zotero 选项卡，请参见 <a href="./faqs/word-addon#word-中没有-zotero-选项卡">故障排除 | 安装 Zotero 的 Word 插件</a> 。</p><p>Zotero 选项卡包含以下图标：</p><table tabindex="0"><thead><tr><th>名称</th><th>图标</th><th>描述</th></tr></thead><tbody><tr><td>添加/编辑引注</td><td><img src="data:image/png;base64," alt="插入引文" width="32" height="32"></td><td>在光标位置添加新引注或编辑光标位置现有的现有引注。</td></tr><tr><td>添加/编辑参考文献表</td><td><img src="data:image/png;base64," alt="添加参考文献表" width="32" height="32"></td><td>在光标位置插入参考文献表或编辑现有书目。</td></tr><tr><td>添加笔记</td><td></td><td>在光标当前位置插入笔记。请注意，此功能不常用，点击后会出现黄色插入框。如果不小心点开了，可以用键盘上的 <code>Esc</code> 键关闭黄色插入框。</td></tr><tr><td>文档首选项</td><td><img src="data:image/png;base64," alt="文档首选项" width="16" height="16"></td><td>打开「文档首选项」窗口，例如更改引文样式。</td></tr><tr><td>刷新</td><td><img src="data:image/png;base64," alt="刷新" width="16" height="16"></td><td>立即刷新所有引注和参考文献表，如当前文档所引用的 Zotero 文库条目题录信息发生变动，则本文档的数据也会更新到最新状态。</td></tr><tr><td>取消链接引注</td><td><img src="data:image/png;base64," alt="unlink" width="18" height="18"></td><td>通过删除域代码来取消文档与 Zotero 文库的链接，之后引注和参考文献表将不再会更新。请注意，此操作不可逆，建议仅在定稿时进行。</td></tr></tbody></table><h2 id="文档首选项" tabindex="-1">文档首选项 <a class="header-anchor" href="#文档首选项" aria-label="Permalink to “文档首选项”">​</a></h2><p><img src="/assets/word%E6%96%87%E6%A1%A3%E9%A6%96%E9%80%89%E9%A1%B9%E7%AA%97%E6%A0%BC.D9lHhC37.png" alt="Word 文档首选项窗格" width="956" height="1080"></p><p>「文档首选项」窗口允许您设置以下针对该文档的设置：</p><ol><li><strong>「参考文献样式」</strong>：一般情况下，你只需要修改这一项，其余设置均保持默认即可。</li><li>「语言」：设置引注和参考文献表的格式的语言。</li><li>「引注显示为」：对于基于注释的样式，例如「China National Standard GB/T 7714-2015（note，Chinese）」，引文是插入为脚注还或尾注。 脚注和尾注的样式和格式由 Word（而不是 Zotero）控制。</li><li><strong>「自动更新引注」</strong> 一般情况下开启即可。当文档中引文非常多，每次更新都会卡顿时，可以关闭此功能，添加一部分或最终手动进行更新。 由于在 macOS 上更新引注通常较慢，故 mac 用户可以选择关闭此选项。</li><li>「高级选项」 <ol><li>「将引文存储为书签」 默认为存储为「字段」。除非您需要使用 LibreOffice 与同事协作，否则应始终选择「字段」。</li><li>「使用 MEDLINE 期刊缩写」 仅对于缩写期刊标题的样式包含此选项。如果勾选此选项（默认值），则 Zotero 中「期刊缩写」字段的内容将被忽略。</li></ol></li></ol><h2 id="添加引注" tabindex="-1">添加引注 <a class="header-anchor" href="#添加引注" aria-label="Permalink to “添加引注”">​</a></h2><p>您可以通过单击「<img src="data:image/png;base64," alt="插入引文" width="16" height="16"> 添加/编辑引注」在当前光标位置插入或编辑引注。</p><div class="tip custom-block github-alert"><p class="custom-block-title">提示</p><p>此按钮只是插入引注，不会在文末自动生成参考文献表。要插入参考文献表，请点击「插入/编辑参考文献表」按钮。</p></div><p>在一个未添加过引文的文档中，按下按钮将先弹出一个「文档首选项」窗口以让你选择一个 CSL 样式，之后再点「添加/编辑引注」将直接显示「引注对话框」，这个对话框可以从 Zotero 库中选择条目，并创建引注。</p><p>打开该对话框后，对话框会默认展示出你在 Zotero 文库列表中已经选中的条目和正在阅读的条目。如果这些条目正是你想要选择的，可以直接单击以选择。</p><p><img src="/assets/word-%E5%BC%95%E6%96%87%E5%AF%B9%E8%AF%9D%E6%A1%86.BfCFjIqy.png" alt="未搜索关键词的引文对话框" width="1080" height="379"></p><p>你也可以在搜索框中键入标题的一部分、一个或多个作者的姓氏和/或年份。匹配项将立即显示在对话框下方。</p><p><img src="/assets/word-%E5%BC%95%E6%96%87%E5%AF%B9%E8%AF%9D%E6%A1%862.BEDAMOtH.png" alt="键入关键词的引文对话框" width="1080" height="329"></p><p>单击某条目可以选择这个条目，也可以用键盘「↑↓」+「Enter」键来选择条目。选中的条目以气泡形状显示在对话框中。</p><p><img src="/assets/word-%E5%BC%95%E6%96%87%E5%AF%B9%E8%AF%9D%E6%A1%863.ByP8ugwb.png" alt="添加了引注的引文对话框" width="1080" height="384"></p><p>要在同一位置引用多篇文献（例如，数字样式为<code>[2，4-6]</code>，作者日期样式为<code>(Smith 1776, Schumpeter 1962）</code>），请在「添加引注」框中一个接一个地添加它们。选择第一个项目后，不要按 Enter/Return 键，而是继续选择下一个条目。</p><p>完成选择后，再次按「Enter/Return」键以插入引注并关闭引注对话框。</p><h3 id="文库模式" tabindex="-1">文库模式 <a class="header-anchor" href="#文库模式" aria-label="Permalink to “文库模式”">​</a></h3><p>「添加引注」对话框有「列表模式」和「文库模式」两种。前者主要通过关键词检索文献，后者可以通过合集来查找文献。</p><p>你可以在对话框右下角切换两种模式，Zotero 默认使用上次使用过的模式，但也可以在设置中指定默认模式。</p><p><img src="/assets/word-%E5%BC%95%E6%96%87%E5%AF%B9%E8%AF%9D%E6%A1%86-%E6%96%87%E5%BA%93%E6%A8%A1%E5%BC%8F.C4wuX9RX.png" alt="引文对话框 - 文库模式" width="1080" height="678"></p><h3 id="引注顺序" tabindex="-1">引注顺序 <a class="header-anchor" href="#引注顺序" aria-label="Permalink to “引注顺序”">​</a></h3><p>某些引文样式要求一个位置内文献按字母顺序排序（例如，<code>(Doe 2000，Grey 1994，Smith 2008)</code>）或按时间顺序排序（<code>(Grey 1994，Doe 2000，Smith 2008)</code>）。Zotero 将自动遵循这些排序规则。</p><details class="details custom-block"><summary>禁用文献自动排序？</summary><p>若要禁用引文中引文的自动排序，请拖动引文以在「添加引文」框中重新排列引文。您也可以单击「添加引文」框右下角的「引用设置」图标，然后取消选中「保持文献自动排序」选项。<em>此选项仅对指定引文排序顺序的引文样式显示。</em> 要恢复自动排序，请重新选中「保持源已排序」选项。</p><p><img src="/assets/word-%E5%BC%95%E6%96%87%E5%AF%B9%E8%AF%9D%E6%A1%86-%E7%A6%81%E7%94%A8%E8%87%AA%E5%8A%A8%E6%8E%92%E5%BA%8F.B5FYjzx3.png" alt="引文对话框禁用自动排序" width="1080" height="294"></p></details><h3 id="孤立的条目" tabindex="-1">孤立的条目 <a class="header-anchor" href="#孤立的条目" aria-label="Permalink to “孤立的条目”">​</a></h3><p>孤立的条目是指存在于 Word 文档中但不存在于 Zotero 文库的参考文献条目。</p><details class="details custom-block"><summary>详细信息</summary><p>在「添加引注」对话框中，您可以单击被引用条目的气泡，然后单击「在我的库中打开（或组库的名称）」以在 Zotero 中查看该条目。</p><p>孤立的条目（未连接到 Zotero 数据库中的任何条目）将没有「在我的库中打开」按钮。</p><p><img src="/assets/word-%E5%BC%95%E6%96%87%E5%AF%B9%E8%AF%9D%E6%A1%86-%E7%BC%96%E8%BE%91%E5%BC%95%E6%B3%A8.CqAdkeAD.png" alt="编辑引文" width="1080" height="457"></p><p>孤立条目通常是以下原因导致的：</p><ul><li>协作者从 TA 自己的文库或您无权访问的群组中插入的</li><li>您已从 Zotero 文库中删除了这些条目</li><li>你曾经有个一样的重复条目 A 和 B，你在文档里插入了 A，然后在 Zotero 里删除了 A 留下了 B（而不是合并）</li></ul></details><p>Zotero 可以正常为孤立条目排序，但由于你的 Zotero 库中没有这个条目，因此你无法修改它的题录信息。若要更新，请将这些文献重新导入您自己的文库，并重新插入。</p><h3 id="在已经添加引注的地方增删引注" tabindex="-1">在已经添加引注的地方增删引注 <a class="header-anchor" href="#在已经添加引注的地方增删引注" aria-label="Permalink to “在已经添加引注的地方增删引注”">​</a></h3><p>如果您想在之前插入的引注中增加/删除条目，或者修改引注的信息，可以将光标定位在引注内（在 Word 中插好的编号角标中间点一下，使输入光标在角标内，此时引注区域会出现灰色阴影），然后再单击「<img src="data:image/png;base64," alt="插入引文" width="16" height="16"> 添加/编辑引注」按钮开始编辑引注。</p><p><img src="/assets/word-%E7%BC%96%E8%BE%91%E5%BC%95%E6%B3%A8.l9CZFj02.png" alt="编辑引注" width="1080" height="707"></p><p>在「添加/编辑引注」对话框中，您可以将光标定位在引用条目的气泡之间，然后继续键入新文献的相关信息来添加新的引用条目，或使用键盘 <code>Backspace</code> 或 <code>Delete</code> 键删除不再需要的引用条目。</p><p><img src="/assets/word-%E5%BC%95%E6%96%87%E5%AF%B9%E8%AF%9D%E6%A1%86-%E5%A2%9E%E5%88%A0%E5%BC%95%E6%B3%A8.D1Y_qyED.png" alt="编辑引注" width="1080" height="194"></p><div class="warning custom-block github-alert"><p class="custom-block-title">警告</p><p>请勿直接修改 Word 中的引注文字（编号等域代码内容）。对引用项的任何修改，都需要在「添加/编辑引注」对话框中进行。手动修改域代码字段将阻止 Zotero 自动更新引注以反映文档中的其他更改（例如，无法自动更新引用角标的编号）。在您进行手动编辑文字后，Zotero 将要求您确认是否要保留编辑并防止引注自动更新。如果您在手动编辑后希望恢复由 Zotero 更新引注内容，可以参照 <a href="./faqs/word-addon#使-zotero-恢复对引文的更新">使 Zotero 恢复对引文的更新</a> 的方法来恢复，或者删除这一整个引注角标，重新插入这几篇文献。</p></div><h3 id="自定义引注" tabindex="-1">自定义引注 <a class="header-anchor" href="#自定义引注" aria-label="Permalink to “自定义引注”">​</a></h3><p>在「添加引注」对话框中，您还可以单击被引用条目的气泡，然后编辑该引用条目的更多信息，如页码等定位符、前后缀、省略作者等。请参考 <a href="#自定义引注">自定义引注</a>。</p><p><img src="/assets/word-%E5%BC%95%E6%96%87%E5%AF%B9%E8%AF%9D%E6%A1%86-%E7%BC%96%E8%BE%91%E5%BC%95%E6%B3%A8.CqAdkeAD.png" alt="编辑引注" width="1080" height="457"></p><h4 id="页码和其他定位符-图、表等" tabindex="-1">页码和其他定位符（图、表等） <a class="header-anchor" href="#页码和其他定位符-图、表等" aria-label="Permalink to “页码和其他定位符（图、表等）”">​</a></h4><details class="details custom-block"><summary>详细信息</summary><p>在某些情况下，您希望引用条目的某个部分，例如某个页面，页码范围或卷（例如，引注 <code>Doe et al., 2001，page 4-7</code> 中的 <code>page 4-7</code>），这种额外的引文特定信息被称为「定位符」。</p><p>引注选项窗口的「page」处有个下拉列表，里面是不同的定位符类型，后面的输入框里输入这个定位符的值。</p><p>要使用其他的定位符，例如「表」，请使用「后缀」。</p><p>您还可以在插入引注时添加页码。搜索条目，在选择条目之前或之后，但在按 Enter 将引注插入到文档中之前，输入 <code>p.34</code>、<code>p34</code>，甚至 <code>34</code>，都可以将页码添加到引注中。</p></details><h4 id="前缀和后缀" tabindex="-1">前缀和后缀 <a class="header-anchor" href="#前缀和后缀" aria-label="Permalink to “前缀和后缀”">​</a></h4><details class="details custom-block"><summary>详细信息</summary><p>有时候，你需要 <code>cf. Tribe 1999， see also see……</code> ，而不只是 <code>Tribe 1999</code>，你就需要「前缀」和「后缀」。</p><p>前缀和后缀字段中的任何文本都可以使用 HTML 标记 <code>&lt;i&gt;斜体&lt;/i&gt;</code>、<code>&lt;b&gt;粗体&lt;/b&gt;</code>、<code>&lt;sub&gt;下标&lt;/sub&gt;</code> 和 <code>&lt;sup&gt;上标&lt;/sup&gt;</code> 进行格式设置。</p><p>前缀和后缀可以应用于引注中的每个条目，以创建复杂的引注。例如：</p><div class="language-plain"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>（参见 Smith 1776 的经典例子; 马克思 1867 年提出和另一种观点）</span></span></code></pre></div><p>通过在「前缀」和「后缀」修改引注始终比直接在 Word 域代码字段中输入内容更可取。手动修改域代码字段将阻止 Zotero 自动更新引注。</p></details><h4 id="省略作者-在文本中使用作者" tabindex="-1">省略作者：在文本中使用作者 <a class="header-anchor" href="#省略作者-在文本中使用作者" aria-label="Permalink to “省略作者：在文本中使用作者”">​</a></h4><details class="details custom-block"><summary>详细信息</summary><p>使用作者日期样式，作者经常被移到文本中，并从以下括号括起来的引文中省略，例如：</p><div class="language-plain"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>……根据 Smith（1776）的说法，劳动分工至关重要……</span></span></code></pre></div><p>这种需要从引注中省略作者，请选中「省略作者」框（产生的引注变成 <code>(1776)</code> 而不是原来的 <code>(Smith，1776)</code>），并将作者的姓名「Smith」作为文档中常规文本的一部分。</p></details><h4 id="其他更改" tabindex="-1">其他更改 <a class="header-anchor" href="#其他更改" aria-label="Permalink to “其他更改”">​</a></h4><div class="info custom-block github-alert"><p class="custom-block-title">信息</p><p>如果是文献的元数据有误，建议在 Zotero 中更正条目元数据，然后刷新 Word 文档。Zotero 会自动更新文档中的引注和参考文献表。</p></div><p>如果您的引注仍未按所需方式显示，您可以直接在文档中编辑引注，但请注意，这样做会阻止 Zotero 自动更新引注以反映文档中的其他更改（例如，对于「同上」或给定名称消除歧义）。在您进行手动编辑后，Zotero 将要求您确认是否要保留编辑并防止引注自动更新。</p><p>最好是在要进行的更改的文本中做注释，等到准备好提交文档，然后在使用「取消链接引文」后的文档副本中进行更改。</p><p>如果您认为 CSL 样式中存在错误，请发布到 Zotero 论坛，并在必要时更正样式。如果样式已更新，则文档将自动更新。</p><h2 id="添加参考文献表" tabindex="-1">添加参考文献表 <a class="header-anchor" href="#添加参考文献表" aria-label="Permalink to “添加参考文献表”">​</a></h2><p>单击「<img src="data:image/png;base64," alt="添加参考文献表" width="16" height="16"> 添加/编辑参考文献表」按钮会在光标位置插入参考文献表。</p><div class="info custom-block github-alert"><p class="custom-block-title">信息</p><p>一般情况下，在文末写一个 <code>参考文献</code> 标题，然后按回车另起一行，再点击这个按钮插入参考文献表。</p></div><p>Zotero 将根据文档中的引文自动更新参考书目。</p><p>在极少数情况下，如果要将未在文档中引用的条目添加到书目中，可以再次单击「添加/编辑参考文献表」按钮，这将打开 <a href="#编辑参考文献表">参考文献表编辑器</a>。</p><div class="warning custom-block github-alert"><p class="custom-block-title">警告</p><p>不要在 Word 中手动编辑参考文献表，这些编辑将在下次 Zotero 刷新文档时被覆盖。</p></div><h3 id="参考文献表段落格式" tabindex="-1">参考文献表段落格式 <a class="header-anchor" href="#参考文献表段落格式" aria-label="Permalink to “参考文献表段落格式”">​</a></h3><p>参考文献表的缩进、悬挂、字体字号、行间距、编号与条目之间的距离等，都是在 Word「书目」样式中修改，请阅读 <a href="./faqs/word-addon">关于引用文献的一揽子问题</a> 中的 Word 样式小节。</p><h2 id="添加笔记" tabindex="-1">添加笔记 <a class="header-anchor" href="#添加笔记" aria-label="Permalink to “添加笔记”">​</a></h2><p>在光标当前位置插入笔记。</p><div class="warning custom-block github-alert"><p class="custom-block-title">警告</p><p>此功能不常用，点击后会出现黄色插入框。如果不小心点开了，可以用键盘上的 <code>Esc</code> 键关闭黄色插入框。</p></div><h2 id="编辑参考文献表" tabindex="-1">编辑参考文献表 <a class="header-anchor" href="#编辑参考文献表" aria-label="Permalink to “编辑参考文献表”">​</a></h2><p>当您在文档中添加和删除引注时，Zotero 将自动更新参考文献表。一般来说，这已经足够了。</p><details class="details custom-block"><summary>详细信息</summary><p>但是，在极少数情况下，您可能希望将未引用的文献添加到参考文献表中（例如，综述中包含的项目，但论文中未引用的项目）或删除文本中引用但不应包含在参考书目中的项目（例如，个人通信）。</p><p>为此，请再次单击「添加/编辑书目」（<img src="data:image/png;base64," alt="添加参考文献表" width="16" height="16">）按钮以打开「编辑书目」窗口：</p><p><img src="/assets/word-%E7%BC%96%E8%BE%91%E5%8F%82%E8%80%83%E6%96%87%E7%8C%AE%E8%A1%A8.BuorVbsW.png" alt="编辑参考文献表" width="700" height="448"></p><p>然后，您可以使用箭头添加或删除项目。</p><p>虽然也可以在此窗口中编辑书目参考文献的文本或格式，但不鼓励这样做。如果您更改了库中的数据，Zotero 不会自动更新此处编辑的引用。在这里编辑参考文献也有些不可靠; 一些用户报告说，当 Zotero 引用时，此处所做的修改有时不会持续存在，以及其他问题。</p><p>如果您需要编辑书目中的项目，最好在提交文档之前将其作为最后一步。首先，保存文档的备份副本。然后，单击「取消链接引文」按钮（<img src="data:image/png;base64," alt="icon-Word-unlink" width="18" height="18">）以断开文档与 Zotero 的连接，并将所有引文和书目转换为常规文本。最后，对参考书目文本进行调整。</p><p>此过程可用于对参考书目进行各种细微的修改，包括：</p><ul><li>在综述或荟萃分析中包含的参考文献之前添加星号 <code>*</code></li><li>以粗体、斜体或全大写设置特定作者的姓名</li><li>添加有关项目的批注或注释</li><li>为书目子部分添加标题（例如，主要来源与次要来源）</li></ul></details><h2 id="定稿-取消链接" tabindex="-1">定稿：取消链接 <a class="header-anchor" href="#定稿-取消链接" aria-label="Permalink to “定稿：取消链接”">​</a></h2><p>删除所有 Zotero 域代码且断开与 Zotero 文库链接。点击后所有的引注和文末的参考文献表都会变成纯文本。</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">警告</p><p>该操作不可逆，一旦断开连接，所有的引注信息都会变成纯文本，无法再自动更新编号和参考文献表，也无法恢复到以前带有链接的状态。</p><p>因此强烈建议在断开连接之前将文档另存一份备用，仅将用于提交/共享的副本断开连接。</p><p>正常地，Zotero 会在取消链接时自动新建一个文档，但如果文档保存在 OneDrive 上，这种自动机制无法生效，Zotero 会弹窗要求你手动新建一个文档。</p></div><h2 id="注意事项与常见问题" tabindex="-1">注意事项与常见问题 <a class="header-anchor" href="#注意事项与常见问题" aria-label="Permalink to “注意事项与常见问题”">​</a></h2><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">警告</p><ul><li>所有的引注/参考文献表的样式修改都应在 <a href="./citation-styles">CSL 引文样式</a> 中进行，而不是直接在 Word 里手动修改！</li><li>对引注顺序更改应在 Word「引注编辑对话框」中进行，而不是直接在 Word 里手动修改！</li><li>所有的条目信息，如作者、标题、期刊、期卷页等，都应在 Zotero 中更新条目信息，而不是直接在 Word 里手动修改！</li></ul></div><div class="tip custom-block"><p class="custom-block-title">常见问题</p><p>插入引文中遇到的一些常见问题，请参见 <a href="./faqs/word-addon">关于 Word 引用的各种问题</a> 。</p></div>`,76),i(d),i(f)])}var l=n(s,[[`render`,c]]);export{o as __pageData,l as default};